  `biyografi` text DEFAULT NULL,
  `durum` tinyint(1) DEFAULT 1,
  `kayit_tarihi` timestamp NULL DEFAULT current_timestamp(),
  `email_dogrulandi` tinyint(1) NOT NULL DEFAULT 1,
  `email_dogrulama_hash` char(64) DEFAULT NULL,
